package main

import (
    "encoding/json"
    "errors"
    "fmt"
    "os"
)

var ErrNotFound = errors.New("not found")
var cases []struct { Code int }
func main() {
    if err := json.Unmarshal([]byte(os.Args[1]), &cases); err != nil { panic(err) }
    enc := json.NewEncoder(os.Stdout)
    for _, in := range cases {
        err := describeFailure(in.Code, ErrNotFound)
        var out any
        if errors.Is(err, ErrNotFound) { out = "not_found" } else {
            var target *InputError
            if errors.As(err, &target) { out = fmt.Sprintf("input:%d", target.Code) }
        }
        if err := enc.Encode(out); err != nil { panic(err) }
    }
}
